import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static int computeSpan(List<Integer> array, int startIndex, int maxTime) {
        int length = 1;
        for (int k = startIndex + 1; k < array.size(); k++) {
            if (array.get(k) - array.get(startIndex) > maxTime)
                break;
            ++length;
        }
        return length;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int count = scanner.nextInt();
        List<Integer> values = new ArrayList<>();
        for (int i = 0; i < count; i++) {
            int val = scanner.nextInt();
            values.add(val);
        }
        int maxTime = scanner.nextInt();
        Collections.sort(values);
        int maxLength = 0;
        for (int i = 0; i < values.size(); i++) {
            int currentSpan = computeSpan(values, i, maxTime);
            if (currentSpan > maxLength)
                maxLength = currentSpan;
        }
        System.out.println(maxLength);
        scanner.close();
    }
}
